-- Plantilla manual; NO incluida en install_migraciones.sql. NO ejecutar sin revisar
-- diagnostico_roles_proceso.sql en la instalación destino.
-- El DDL_CORREGIDO_F5.sql indicado define ROL_ID_ROL como
-- GENERATED BY DEFAULT ON NULL AS IDENTITY; por eso el INSERT omite el ID.
-- Solo inserta roles faltantes si la base destino confirma esa identidad. Si usa una secuencia,
-- trigger u otro generador, adaptar el INSERT a ese mecanismo confirmado.
-- No cambia roles existentes, no activa roles inactivos y no asigna usuarios.
DECLARE
  v_identity NUMBER;
  v_otras_obligatorias NUMBER;
  v_cantidad NUMBER;
  v_activo NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_identity
    FROM user_tab_identity_cols
   WHERE table_name = 'ROL' AND column_name = 'ROL_ID_ROL';
  IF v_identity <> 1 THEN
    RAISE_APPLICATION_ERROR(-20011, 'ROL_ID_ROL no es identity; confirma el generador real antes de insertar.');
  END IF;
  SELECT COUNT(*) INTO v_otras_obligatorias
    FROM user_tab_columns
   WHERE table_name = 'ROL' AND nullable = 'N'
     AND column_name NOT IN ('ROL_ID_ROL', 'ROL_NOMBRE_ROL', 'ROL_ACTIVO');
  IF v_otras_obligatorias > 0 THEN
    RAISE_APPLICATION_ERROR(-20014, 'ROL tiene columnas obligatorias adicionales; adapta el INSERT a la estructura real.');
  END IF;

  FOR r IN (SELECT column_value AS nombre FROM TABLE(sys.odcivarchar2list(
    'OPERADOR_CXP', 'APROBADOR_CXP', 'TESORERIA_CXP', 'SUPERVISOR_CXP'))) LOOP
    SELECT COUNT(*), MIN(rol_activo)
      INTO v_cantidad, v_activo
      FROM rol
     WHERE REGEXP_REPLACE(UPPER(rol_nombre_rol), '[[:space:]]', '') = r.nombre;
    IF v_cantidad > 1 THEN
      RAISE_APPLICATION_ERROR(-20012, 'Nombre de rol ambiguo: ' || r.nombre);
    ELSIF v_cantidad = 1 AND NVL(v_activo, 0) <> 1 THEN
      RAISE_APPLICATION_ERROR(-20013, 'El rol ya existe pero está inactivo: ' || r.nombre);
    ELSIF v_cantidad = 0 THEN
      INSERT INTO rol (rol_nombre_rol, rol_activo) VALUES (r.nombre, 1);
    END IF;
  END LOOP;
END;
/
-- Sin COMMIT: revisar las filas nuevas y decidir COMMIT o ROLLBACK.
